'use client';

import { useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { cn } from '@/registry/ndeko/lib/utils';

import { BentoCard } from './bento-card';
import { METHOD } from './data';

const STEP_MS = 2800;

function stepTextOf(isActive: boolean) {
  if (isActive) {
    return 'text-foreground';
  }
  return 'text-muted-foreground';
}

function descriptionRowsOf(isActive: boolean) {
  if (isActive) {
    return 'grid-rows-[1fr]';
  }
  return 'grid-rows-[0fr]';
}

function barScaleOf(isActive: boolean) {
  if (isActive) {
    return 'scale-y-100';
  }
  return 'scale-y-0';
}

function currentOf(isActive: boolean) {
  if (isActive) {
    return 'step' as const;
  }
  return undefined;
}

export function MethodCard({ className }: { className?: string }) {
  const [activeIndex, setActiveIndex] = useState(0);
  const steps = METHOD.slice(1).map((step, offset) => ({
    after: STEP_MS,
    run: () => setActiveIndex(offset + 1),
  }));
  const { ref } = useAutoplay(steps, {
    loopAfter: STEP_MS,
    onReset: () => setActiveIndex(0),
  });

  useKeptHeight(ref);

  return (
    <BentoCard title='How I work' className={className}>
      <div ref={ref}>
        <ol className='relative flex flex-col'>
          <span
            aria-hidden='true'
            className='bg-foreground/[0.08] absolute inset-y-3 start-0 w-0.5 rounded-full'
          />
          {METHOD.map((step, index) => {
            const isActive = index === activeIndex;

            return (
              <li key={step.id}>
                <button
                  type='button'
                  aria-current={currentOf(isActive)}
                  onClick={() => setActiveIndex(index)}
                  className='focus-visible:ring-ring/25 relative flex w-full flex-col gap-1 rounded-lg py-3 ps-4 pe-2 text-start outline-none focus-visible:ring-[3px]'
                >
                  <span
                    aria-hidden='true'
                    className={cn(
                      'bg-primary absolute inset-y-3 start-0 w-0.5 rounded-full transition-[scale] duration-300 ease-(--ease-out-strong) motion-reduce:transition-none',
                      barScaleOf(isActive)
                    )}
                  />
                  <span
                    className={cn(
                      'flex items-baseline gap-2 text-[13px] font-medium transition-colors duration-200',
                      stepTextOf(isActive)
                    )}
                  >
                    <span className='text-xs tabular-nums'>{index + 1}</span>
                    {step.title}
                  </span>
                  <span
                    className={cn(
                      'grid transition-[grid-template-rows] duration-300 ease-(--ease-out-strong) motion-reduce:transition-none',
                      descriptionRowsOf(isActive)
                    )}
                  >
                    <span className='text-muted-foreground overflow-hidden text-[13px] text-pretty'>
                      {step.description}
                    </span>
                  </span>
                </button>
              </li>
            );
          })}
        </ol>
      </div>
    </BentoCard>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { LoaderCircleIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';
import { StatusOrb } from '@/registry/ndeko/ui/status-orb';

import { NEWSLETTER } from './data';

type Status = 'idle' | 'submitting' | 'subscribed';

const SUBMIT_DELAY_MS = 800;

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const PANEL_TRANSITION: Transition = {
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1],
};

const LABEL_TRANSITION: Transition = {
  type: 'spring',
  bounce: 0,
  duration: 0.3,
};

const INSTANT: Transition = { duration: 0 };

const PANEL_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.98, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.98, filter: 'blur(2px)' },
};

const SPINNER_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function emailErrorOf(value: string) {
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    return 'Enter an email address to subscribe';
  }
  const isEmailShaped = EMAIL_PATTERN.test(trimmed);
  if (!isEmailShaped) {
    return 'Check the address, it should look like name@example.com';
  }
  return null;
}

function submitLabelOf(isSubmitting: boolean) {
  if (isSubmitting) {
    return 'Subscribing';
  }
  return 'Subscribe';
}

function panelVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return PANEL_VARIANTS;
}

function spinnerVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SPINNER_VARIANTS;
}

function labelTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return LABEL_TRANSITION;
}

export function NewsletterForm() {
  const [email, setEmail] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [hasTriedSubmit, setHasTriedSubmit] = useState(false);
  const [status, setStatus] = useState<Status>('idle');
  const inputRef = useRef<HTMLInputElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const panelVariants = panelVariantsOf(shouldReduceMotion);
  const spinnerVariants = spinnerVariantsOf(shouldReduceMotion);
  const labelTransition = labelTransitionOf(shouldReduceMotion);
  const isSubmitting = status === 'submitting';
  const isSubscribed = status === 'subscribed';
  const hasError = error !== null;
  const submitLabel = submitLabelOf(isSubmitting);
  const trimmedEmail = email.trim();

  useEffect(() => {
    if (!isSubmitting) {
      return;
    }
    const timeout = window.setTimeout(() => {
      setStatus('subscribed');
    }, SUBMIT_DELAY_MS);
    return () => window.clearTimeout(timeout);
  }, [isSubmitting]);

  function changeEmail(event: React.ChangeEvent<HTMLInputElement>) {
    const nextEmail = event.target.value;
    setEmail(nextEmail);
    if (hasTriedSubmit) {
      setError(emailErrorOf(nextEmail));
    }
  }

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const nextError = emailErrorOf(email);
    setHasTriedSubmit(true);
    setError(nextError);
    if (nextError) {
      inputRef.current?.focus();
      return;
    }
    setStatus('submitting');
  }

  function startOver() {
    setEmail('');
    setError(null);
    setHasTriedSubmit(false);
    setStatus('idle');
  }

  return (
    <AnimatedSize className='w-full max-w-sm' contentClassName='relative'>
      <AnimatePresence mode='popLayout' initial={false}>
        {isSubscribed && (
          <motion.div
            key='subscribed'
            role='status'
            variants={panelVariants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={PANEL_TRANSITION}
            className='flex items-start gap-3'
          >
            <StatusOrb tone='success' size='sm' />
            <div className='flex min-w-0 flex-col items-start gap-0.5'>
              <p className='text-[13px] font-medium'>You are subscribed</p>
              <p className='text-muted-foreground text-[13px]'>
                The next update goes to{' '}
                <span className='text-foreground font-medium break-all'>
                  {trimmedEmail}
                </span>
                .
              </p>
              <Button
                variant='link'
                size='sm'
                className='h-auto px-0 py-0.5'
                onClick={startOver}
              >
                Use another address
              </Button>
            </div>
          </motion.div>
        )}
        {!isSubscribed && (
          <motion.form
            key='form'
            noValidate
            onSubmit={submit}
            variants={panelVariants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={PANEL_TRANSITION}
          >
            <Field invalid={hasError}>
              <FieldLabel>{NEWSLETTER.label}</FieldLabel>
              <div className='flex gap-2'>
                <Input
                  ref={inputRef}
                  type='email'
                  name='email'
                  autoComplete='email'
                  placeholder='you@example.com'
                  value={email}
                  onChange={changeEmail}
                  readOnly={isSubmitting}
                />
                <Button
                  type='submit'
