  const message = spokenUnless(isAutoplaying, messageOf(lastEntry));
  const caretStyle = { left: `${state.typed.length}ch` };

  function edit(event: React.ChangeEvent<HTMLInputElement>) {
    act({ type: 'edit', text: event.target.value });
